from itertools import permutations

def f(datasets):
    result = []
    descriptors = []
    des_vars = {'x1': False, 'x2': False, 'r': False}
    current = None
    for i, desc in enumerate(datasets):
        valid = True
        if current is None:
            if any(var in desc[0] for var in des_vars.keys()):
                descriptors.append(desc)
        else:
            valid = False
            for var in des_vars.keys():
                if var + '1' in current[0] and var + '2' in desc[0]:
                    valid = True
            for var in des_vars.keys():
                if var + '1' in desc[0]:
                    valid = valid and desc[0][var + '1'] > current[0][var + '1']
                if var + '2' in desc[0]:
                    valid = valid and desc[0][var + '2'] < current[0][var + '2']

